<script setup lang="ts">const props=defineProps<{locale:'zh'|'en'}>();const input=ref('{"hello":"world","count":1}');const compact=ref(false);const result=computed(()=>{try{return JSON.stringify(JSON.parse(input.value),null,compact.value?0:2)}catch(e){return `${props.locale==='zh'?'语法错误':'Syntax error'}: ${(e as Error).message}`}});const {copied,copy}=useCopy()</script><template><div class="tool-form"><div class="segmented"><button :class="{active:!compact}" @click="compact=false">{{locale==='zh'?'格式化':'Format'}}</button><button :class="{active:compact}" @click="compact=true">{{locale==='zh'?'压缩':'Minify'}}</button></div><label>{{locale==='zh'?'输入 JSON':'Input JSON'}}<textarea v-model="input" rows="8" spellcheck="false" /></label><div class="result-header"><span>OUTPUT</span><button type="button" @click="copy(result)">{{copied?(locale==='zh'?'已复制':'Copied'):(locale==='zh'?'复制':'Copy')}}</button></div><pre class="code-result">{{result}}</pre></div></template>